class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        trust_score = [0] * (n + 1)
        for a, b in trust:
            trust_score[a] -= 1
            trust_score[b] += 1
        for i in range(1, n + 1):
            if trust_score[i] == n - 1:
                return i
        return -1

class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        vector<int> trustScore(n + 1, 0);
        for (auto& t : trust) {
            --trustScore[t[0]];
            ++trustScore[t[1]];
        }
        for (int i = 1; i <= n; ++i) {
            if (trustScore[i] == n - 1) return i;
        }
        return -1;
    }
};

class Solution {
    public int findJudge(int n, int[][] trust) {
        int[] score = new int[n + 1];
        for (int[] t : trust) {
            score[t[0]]--;
            score[t[1]]++;
        }
        for (int i = 1; i <= n; i++) {
            if (score[i] == n - 1) return i;
        }
        return -1;
    }
}

var findJudge = function(n, trust) {
    const score = new Array(n + 1).fill(0);
    for (const [a, b] of trust) {
        score[a]--;
        score[b]++;
    }
    for (let i = 1; i <= n; i++) {
        if (score[i] === n - 1) return i;
    }
    return -1;
};
